import { computeKeywordIdf, weightedKeywordJaccard } from '@/viz/graph';
import { getStoredUserPapers, addStoredUserPaper, removeStoredUserPaper, updateStoredUserPaper, markStoredUserPapersProposed } from './userPapers';
import { assignPaperIds } from './paperIds';
import { keywordsOf } from './roles';
import { reviewConfig } from './review';
import { saveWorkspace } from './workspace';

const BASE_PATH = import.meta.env.BASE_URL || '/';
const PAPERS_FILE = 'bpm_research_artifacts_anonymized.json';

let cachedPapers = null;
let cachedConfig = null;
let cachedKeywordLinks = null;

/** Where the papers come from: the published dataset, or the visitor's own
 * review stored in this browser (lib/workspace.js). Set once at startup by
 * main.jsx: { kind: 'published' | 'workspace', notice, and for a review
 * name, schema, papers, savedAt }. `notice` explains a fallback to the
 * published dataset. */
let source = { kind: 'published', notice: null };

export function setDataSource(next) {
  source = { notice: null, ...next };
  cachedPapers = null;
  cachedKeywordLinks = null;
  cachedConfig = null;
}

export const getDataSource = () => source;

/** Stores the review's papers after coding and shows them from now on.
 * The views pick them up when they load the papers again (see
 * lib/codingState.jsx). */
export async function saveReviewPapers(papers) {
  if (source.kind !== 'workspace') throw new Error('No review is shown.');
  const record = await saveWorkspace({ name: source.name, schema: source.schema, papers, active: true });
  source = { ...source, papers, savedAt: record.savedAt };
  cachedPapers = null;
  cachedKeywordLinks = null;
  return record;
}

export async function loadPapers() {
  if (cachedPapers) return cachedPapers;

  if (source.kind === 'workspace') {
    // Papers added with Add Paper belong to the published dataset, so they
    // are not mixed into the visitor's own review.
    // _reviewIndex is the paper's place in the stored review, used to save
    // it back after coding.
    cachedPapers = assignPaperIds(source.papers).map((p, i) => ({ ...p, _reviewIndex: i }));
    return cachedPapers;
  }

  // source.records: the full dataset unlocked by a reviewer link
  // (lib/reviewerAccess.js), shown instead of the published file.
  let records = source.records;
  if (!records) {
    const res = await fetch(`${BASE_PATH}data/${PAPERS_FILE}`);
    if (!res.ok) throw new Error(`Failed to load ${PAPERS_FILE}: ${res.status}`);
    records = await res.json();
  }
  const allRecords = [...records, ...getStoredUserPapers()];

  cachedPapers = assignPaperIds(allRecords);
  return cachedPapers;
}

/** Precomputed keyword-similarity scores for pairs involving anonymized
 * papers, so the graph can draw Shared Keywords edges for them without the
 * client ever having their real keyword text (see
 * scripts/build-keyword-links.mjs). Missing file just means no such edges. */
export async function loadKeywordLinks() {
  if (cachedKeywordLinks) return cachedKeywordLinks;
  // The full dataset carries the real keywords, so the graph computes all
  // keyword edges itself; the precomputed links only stand in for them.
  if (source.kind === 'workspace' || source.records) {
    cachedKeywordLinks = [];
    return cachedKeywordLinks;
  }
  const linksFile = PAPERS_FILE.replace(/\.json$/, '.keyword-links.json');
  const res = await fetch(`${BASE_PATH}data/${linksFile}`);
  try {
    cachedKeywordLinks = res.ok ? await res.json() : [];
  } catch {
    cachedKeywordLinks = [];
  }
  return cachedKeywordLinks;
}

export async function addUserPaper(record) {
  addStoredUserPaper(record);
  cachedPapers = null;
  const papers = await loadPapers();
  return papers.find((p) => p._userKey === record._userKey) || null;
}

export async function addUserPapers(records) {
  records.forEach(addStoredUserPaper);
  cachedPapers = null;
  const papers = await loadPapers();
  const keys = new Set(records.map((r) => r._userKey));
  return papers.filter((p) => keys.has(p._userKey));
}

export async function updateUserPaper(record) {
  updateStoredUserPaper(record);
  cachedPapers = null;
  const papers = await loadPapers();
  return papers.find((p) => p._userKey === record._userKey) || null;
}

export async function markUserPapersProposed(userKeys) {
  markStoredUserPapersProposed(userKeys, new Date().toISOString());
  cachedPapers = null;
  return loadPapers();
}

export async function removeUserPaper(userKey) {
  removeStoredUserPaper(userKey);
  cachedPapers = null;
  return loadPapers();
}

export async function loadConfig() {
  if (cachedConfig) return cachedConfig;
  const res = await fetch(`${BASE_PATH}data/site.config.json`);
  const config = res.ok ? await res.json() : {};
  // The texts and lists describing the published dataset do not fit the
  // visitor's own review.
  cachedConfig = source.kind === 'workspace' ? reviewConfig(config, source) : config;
  return cachedConfig;
}

let cachedSchema = null;

/** The JSON Schema named by about.schemaFile in site.config.json. Its
 * x-ariadne annotations decide what the views show (see lib/scheme.js). */
export async function loadSchema() {
  if (cachedSchema) return cachedSchema;
  const config = await loadConfig();
  const file = config.about?.schemaFile || 'research_artifacts.schema.json';
  const res = await fetch(`${BASE_PATH}data/${file}`);
  if (!res.ok) throw new Error(`Could not load the schema ${file} (${res.status}).`);
  try {
    cachedSchema = await res.json();
  } catch {
    throw new Error(`The schema ${file} is not valid JSON.`);
  }
  return cachedSchema;
}

export function getPaperById(papers, id) {
  return papers.find((p) => p._id === id) || null;
}

export function getRelatedPapers(papers, paper, limit = 6) {
  const keywords = keywordsOf(paper);
  if (keywords.length === 0) return [];

  const idf = computeKeywordIdf(papers.map((p) => ({ keywords: keywordsOf(p) })));

  return papers
    .filter((p) => p._id !== paper._id)
    .map((p) => ({
      paper: p,
      score: weightedKeywordJaccard(keywords, keywordsOf(p), idf),
    }))
    .filter(({ score }) => score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, limit)
    .map(({ paper: p }) => ({ ...p, relationship: 'shared-keywords' }));
}
