/**
 * The visitor's own review: a schema and the papers coded against it, kept
 * in this browser only (IndexedDB). When it is switched on, the site starts
 * with it instead of the published dataset (see main.jsx).
 *
 * Stored as one record: { name, schema, papers, active, savedAt }. Every
 * call fails soft: without IndexedDB (private windows, blocked site data,
 * Node) loading returns null and saving reports the error, so the
 * published dataset always works.
 */
const DB_NAME = 'ariadne-lit:workspace';
const STORE = 'workspace';
const KEY = 'current';

function openDb() {
  return new Promise((resolve, reject) => {
    if (typeof indexedDB === 'undefined') {
      reject(new Error('This browser does not allow the site to store data.'));
      return;
    }
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE);
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('The browser storage could not be opened.'));
    request.onblocked = () => reject(new Error('The browser storage is in use by another tab.'));
  });
}

async function run(mode, action) {
  const db = await openDb();
  try {
    return await new Promise((resolve, reject) => {
      const tx = db.transaction(STORE, mode);
      const request = action(tx.objectStore(STORE));
      tx.oncomplete = () => resolve(request?.result);
      tx.onerror = () => reject(tx.error || new Error('The browser storage could not be written.'));
      tx.onabort = () => reject(tx.error || new Error('The browser storage refused the data (it may be full).'));
    });
  } finally {
    db.close();
  }
}

/** The stored review, or null when there is none or storage is unavailable. */
export async function loadWorkspace() {
  try {
    const record = await run('readonly', (store) => store.get(KEY));
    return record && record.schema && Array.isArray(record.papers) ? record : null;
  } catch {
    return null;
  }
}

/** Stores the review, replacing any earlier one. Throws with a readable
 * message when the browser refuses. */
export async function saveWorkspace({ name, schema, papers, active = false }) {
  const record = { name: name || 'My review', schema, papers, active, savedAt: new Date().toISOString() };
  await run('readwrite', (store) => store.put(record, KEY));
  return record;
}

/** Switches the stored review on or off without changing it. */
export async function setWorkspaceActive(active) {
  const record = await loadWorkspace();
  if (!record) throw new Error('There is no stored review to switch.');
  return saveWorkspace({ ...record, active });
}

/** Deletes the stored review. */
export async function clearWorkspace() {
  await run('readwrite', (store) => store.delete(KEY));
}
