import { DIMENSIONS, INDICATORS, INDICATOR_GROUP, MISSING, unitValues } from './analysis';
import { installDetail } from './detail';
import { installFilters } from './facets';
import { installRoles } from './roles';
import { humanize } from './humanize';
import { extractAttributes } from './schemaMapping';

/**
 * Builds the views' attribute definitions from the schema's x-ariadne
 * annotations, so a dataset's schema decides what the views show instead of
 * the code.
 *
 * applyScheme must run before the modules that read DIMENSIONS or the
 * filters when they load (similarity, the filter bar, the views). main.jsx loads the schema first and
 * imports the app afterwards; scripts/check-scheme.mjs does the same.
 */

/** Calculations an attribute can name with x-ariadne "derive". Each gets the
 * attribute's value and returns its codes. */
const DERIVATIONS = {
  implementationStatus: (impl) => {
    if (!impl || impl.existence === undefined || impl.existence === null) return [];
    if (!impl.existence) return ['no_implementation'];
    if (impl.availability === true) return ['implementation_available'];
    if (impl.availability === false) return ['implementation_not_available'];
    return ['implementation_availability_unknown'];
  },
};

/** An attribute is a dimension when it can be the rows and columns of the
 * Co-occurrence matrix: the coded attributes the views compare papers by. */
const DIMENSION_USE = 'patterns.rowsColumns';

/** Attribute kinds whose values are shown as coded rather than humanized. */
const RAW_KINDS = new Set(['number', 'text', 'list']);

export class SchemeError extends Error {}

const asArray = (v) => (Array.isArray(v) ? v : v === undefined || v === null || v === '' ? [] : [v]);

const readPath = (segments) => (node) => segments.reduce((cur, key) => (cur && typeof cur === 'object' ? cur[key] : undefined), node);

/** Splits an attribute path into its level and the path inside that level.
 * Attributes under contribution.artifacts[] are coded per artifact; all
 * others per paper. */
function locate(path) {
  const segments = path.split('.');
  if (segments[0] === 'contribution' && segments[1] === 'artifacts[]') {
    const inner = segments.slice(2);
    if (inner.some((s) => s.endsWith('[]'))) throw new SchemeError(`${path}: lists inside an artifact are not supported.`);
    return { level: 'artifact', segments: inner };
  }
  if (segments.some((s) => s.endsWith('[]'))) throw new SchemeError(`${path}: only contribution.artifacts may hold a list of objects.`);
  return { level: 'paper', segments };
}

function toDimension(attribute) {
  const settings = attribute.annotation || {};
  const { level, segments } = locate(attribute.path);
  const read = readPath(segments);
  let getter = read;
  if (settings.derive) {
    const derive = DERIVATIONS[settings.derive];
    if (!derive) throw new SchemeError(`${attribute.path}: unknown derive "${settings.derive}". Known: ${Object.keys(DERIVATIONS).join(', ')}.`);
    getter = (node) => derive(read(node));
  }
  return {
    key: settings.key || attribute.name,
    path: attribute.path,
    level,
    getter,
    uses: settings.uses || [],
    description: attribute.description || '',
    ...(attribute.kind === 'number' ? { numeric: true } : {}),
    ...(settings.emptyValue ? { emptyValue: settings.emptyValue } : {}),
  };
}

function ordered(dimensions, order) {
  if (!order) return dimensions;
  if (!Array.isArray(order)) throw new SchemeError('x-ariadne "order" must be a list of dimension keys.');
  const byKey = new Map(dimensions.map((d) => [d.key, d]));
  const unknown = order.filter((k) => !byKey.has(k));
  if (unknown.length) throw new SchemeError(`x-ariadne "order" names ${unknown.join(', ')}, which ${unknown.length === 1 ? 'is not a dimension' : 'are not dimensions'}.`);
  return [...order.map((k) => byKey.get(k)), ...dimensions.filter((d) => !order.includes(d.key))];
}

/** Reads an attribute's values for a whole paper: per-artifact attributes
 * are collected across the paper's artifacts. */
function paperValuesOf(attribute) {
  const { level, segments } = locate(attribute.path);
  const read = readPath(segments);
  const values = level === 'artifact'
    ? (paper) => (paper.contribution?.artifacts || []).flatMap((a) => asArray(read(a)))
    : (paper) => asArray(read(paper));
  return (paper) => [...new Set(values(paper).map(String))];
}

/** One filter per attribute marked "filters". Attributes sharing a
 * "combineAs" name become one filter whose values are the names of those of
 * them that are true (yes/no attributes). */
function buildFacets(attributes, dimensions) {
  const facets = [];
  const combined = new Map();
  attributes.filter((a) => a.annotation?.uses?.includes('filters')).forEach((a) => {
    const settings = a.annotation;
    if (settings.combineAs) {
      if (a.kind !== 'boolean') throw new SchemeError(`${a.path}: "combineAs" works only for yes/no attributes.`);
      const read = paperValuesOf(a);
      let facet = combined.get(settings.combineAs);
      if (!facet) {
        facet = { key: settings.combineAs, label: humanize(settings.combineAs), members: [] };
        facet.getValues = (paper) => facet.members.filter((m) => m.read(paper).includes('true')).map((m) => m.name);
        combined.set(settings.combineAs, facet);
        facets.push(facet);
      }
      facet.members.push({ name: a.name, read });
      return;
    }
    const key = settings.key || a.name;
    const dimension = dimensions.find((d) => d.path === a.path);
    facets.push({
      key,
      label: settings.label || humanize(key),
      ...(a.kind === 'number' ? { sortByValue: true } : {}),
      ...(RAW_KINDS.has(a.kind) ? { raw: true } : {}),
      getValues: dimension
        ? (paper) => unitValues({ paper, artifacts: paper.contribution?.artifacts || [] }, dimension).filter((v) => v !== MISSING)
        : paperValuesOf(a),
    });
  });
  return facets.map(({ members, ...f }) => f);
}

/** Puts the filters into the groups listed in x-ariadne "filterGroups";
 * filters not listed there go into a last group, More. Without
 * filterGroups, all filters are shown one by one. */
function groupFacets(facets, groups) {
  const seen = new Set();
  facets.forEach((f) => {
    if (seen.has(f.key)) throw new SchemeError(`Two filters are called "${f.key}". Give one an x-ariadne "key".`);
    seen.add(f.key);
  });
  if (!groups) return [{ id: 'core', label: null, facets }];
  if (!Array.isArray(groups)) throw new SchemeError('x-ariadne "filterGroups" must be a list of groups.');
  const byKey = new Map(facets.map((f) => [f.key, f]));
  const listed = new Set();
  const out = groups.map((g, i) => {
    const unknown = (g.filters || []).filter((k) => !byKey.has(k));
    if (unknown.length) throw new SchemeError(`Filter group "${g.label || g.id || i + 1}" lists ${unknown.join(', ')}, which ${unknown.length === 1 ? 'is not a filter' : 'are not filters'}.`);
    (g.filters || []).forEach((k) => listed.add(k));
    return { id: g.id || `group${i + 1}`, label: g.label || null, facets: (g.filters || []).map((k) => byKey.get(k)) };
  });
  const rest = facets.filter((f) => !listed.has(f.key));
  return rest.length ? [...out, { id: 'more', label: 'More', facets: rest }] : out;
}

/** The paths of the Year and Keywords roles and of the Publication Timeline
 * rows. All three are read per paper, so they may not lie inside an
 * artifact. */
function buildRoles(attributes, dimensions) {
  const withRole = (role) => attributes.find((a) => a.annotation?.role === role);
  const paperLevel = (a, what) => {
    if (a && locate(a.path).level !== 'paper') throw new SchemeError(`${a.path}: the ${what} must be coded per paper, not inside an artifact.`);
    return a;
  };
  const year = paperLevel(withRole('year'), 'Year');
  const keywords = paperLevel(withRole('keywords'), 'Keywords');
  const rows = attributes.filter((a) => a.annotation?.uses?.includes('overview.timelineRows'));
  if (rows.length > 1) throw new SchemeError(`Only one attribute can be the Publication Timeline rows; ${rows.map((a) => a.path).join(' and ')} both are.`);
  const row = paperLevel(rows[0], 'Publication Timeline rows');
  const valueOrder = row?.annotation.valueOrder;
  if (valueOrder !== undefined && !(Array.isArray(valueOrder) && valueOrder.every((v) => typeof v === 'string'))) {
    throw new SchemeError(`${row.path}: "valueOrder" must be a list of values.`);
  }
  return {
    yearPath: year.path,
    keywordsPath: keywords?.path || null,
    timelineRowPath: row?.path || null,
    timelineRowKey: row ? dimensions.find((d) => d.path === row.path)?.key || row.annotation.key || row.name : null,
    // The order of the rows: x-ariadne "valueOrder", else the value list.
    timelineRowOrder: valueOrder || row?.values?.filter((v) => !/^other$/i.test(v)) || [],
  };
}

/** True when the schema describes the path (segments ending in [] step
 * into a list's items). */
function schemaHasPath(schema, path) {
  let node = schema;
  for (const raw of path.split('.')) {
    const name = raw.replace(/\[\]$/, '');
    node = node?.properties?.[name];
    if (raw.endsWith('[]')) node = node?.items;
    if (!node) return false;
  }
  return true;
}

const INDICATOR_TESTS = {
  equals: (expected) => (v) => v === expected,
  includes: (value) => (v) => asArray(v).includes(value),
  includesAny: (values) => (v) => asArray(v).some((x) => values.includes(x)),
  nonEmpty: () => (v) => asArray(v).length > 0,
  greaterThan: (limit) => (v) => (Number(v) || 0) > limit,
};

/** The fixed Trends indicators from x-ariadne "indicators": { label, items:
 * [{ id, label, path, <test> }] }, where <test> is one of equals, includes,
 * includesAny, nonEmpty or greaterThan. A paper meets an indicator on a
 * per-artifact path when any of its artifacts does. */
function buildIndicators(schema, spec) {
  if (!spec) return { label: 'Indicators', items: [] };
  const seen = new Set();
  const items = (spec.items || []).map((item) => {
    const where = `Indicator "${item.id || item.label}"`;
    if (!item.id || !item.label || !item.path) throw new SchemeError(`${where} needs an id, a label and a path.`);
    if (seen.has(item.id)) throw new SchemeError(`Two indicators have the id "${item.id}".`);
    seen.add(item.id);
    if (!schemaHasPath(schema, item.path)) throw new SchemeError(`${where}: the schema has no attribute at ${item.path}.`);
    const tests = Object.keys(INDICATOR_TESTS).filter((t) => t in item);
    if (tests.length !== 1) throw new SchemeError(`${where} needs exactly one of ${Object.keys(INDICATOR_TESTS).join(', ')}.`);
    const check = INDICATOR_TESTS[tests[0]](item[tests[0]]);
    const { level, segments } = locate(item.path);
    const read = readPath(segments);
    return {
      id: item.id,
      label: item.label,
      ...(item.includesAny ? { values: item.includesAny } : {}),
      ...(item.valuesLabel ? { valuesLabel: item.valuesLabel } : {}),
      test: level === 'artifact'
        ? (paper) => (paper.contribution?.artifacts || []).some((a) => check(read(a)))
        : (paper) => check(read(paper)),
    };
  });
  return { label: spec.label || 'Indicators', items };
}

/** Shown in the detail panel's header, not as fields. */
const BIBLIOGRAPHIC = new Set(['metadata.title', 'metadata.authors', 'metadata.doi_or_url', 'metadata.conference_name', 'metadata.conference_abbreviation']);

/** The fields of the detail panel, artifact cards and Compare table, from
 * the schema's structure and x-ariadne "detail": { sections: { path: title },
 * hidden: [paths], showWith: { path: siblingPath }, labels: { path: label },
 * compare: [paths] }. Nested objects are shown flat, in schema order. */
function buildDetail(schema, attributes, roles, dimensions) {
  const spec = schema['x-ariadne']?.detail || {};
  const hidden = new Set(spec.hidden || []);
  const skip = new Set([...BIBLIOGRAPHIC, roles.yearPath, roles.timelineRowPath].filter(Boolean));
  const annotations = new Map(attributes.map((a) => [a.path, a.annotation || {}]));

  const field = (path, name, base) => {
    const settings = annotations.get(path) || {};
    const relative = (p) => (base ? p.slice(base.length + 1) : p).split('.');
    // "x_other" and an "other" inside object x hold the name of an "Other" value of x.
    const parent = path.split('.').slice(-2, -1)[0]?.replace(/\[\]$/, '');
    const other = name.endsWith('_other') ? name.slice(0, -'_other'.length) : name === 'other' ? parent : null;
    const label = spec.labels?.[path] || settings.label || (other ? `Other ${humanize(other)}` : humanize(settings.key || name));
    const showWith = spec.showWith?.[path];
    return {
      path,
      label,
      read: readPath(relative(path)),
      ...(showWith ? { showWith: readPath(relative(showWith)) } : {}),
    };
  };
  const flatten = (node, path, base) => Object.entries(node?.properties || {}).flatMap(([name, child]) => {
    const childPath = `${path}.${name}`;
    if (hidden.has(childPath) || skip.has(childPath)) return [];
    if (child.type === 'object' || child.properties) return flatten(child, childPath, base);
    if (child.type === 'array' && child.items?.properties) return [];
    return [field(childPath, name, base)];
  });

  const paperFields = [];
  const sections = [];
  let artifacts = { title: 'Artifacts', fields: [] };
  Object.entries(schema.properties || {}).forEach(([top, node]) => {
    Object.entries(node?.properties || {}).forEach(([name, child]) => {
      const path = `${top}.${name}`;
      if (hidden.has(path) || skip.has(path)) return;
      if (child.type === 'array' && child.items?.properties) {
        if (path === 'contribution.artifacts') {
          const itemPath = `${path}[]`;
          artifacts = { title: spec.sections?.[itemPath] || spec.sections?.[path] || 'Artifacts', fields: flatten(child.items, itemPath, itemPath) };
        }
        return;
      }
      if (child.type === 'object' || child.properties) {
        sections.push({ title: spec.sections?.[path] || humanize(name), fields: flatten(child, path, null) });
        return;
      }
      paperFields.push(field(path, name, null));
    });
  });

  const compareRows = (spec.compare || dimensions
    .filter((d) => d.level === 'paper' && d.path !== roles.yearPath && d.path !== roles.timelineRowPath)
    .map((d) => d.path)
  ).map((path) => {
    const { level, segments } = locate(path);
    if (level !== 'paper') throw new SchemeError(`detail.compare: ${path} is coded per artifact; the Compare table rows are per paper.`);
    if (!schemaHasPath(schema, path)) throw new SchemeError(`detail.compare: the schema has no attribute at ${path}.`);
    const name = segments[segments.length - 1];
    const settings = annotations.get(path) || {};
    const kind = attributes.find((a) => a.path === path)?.kind || null;
    return { path, kind, label: spec.labels?.[path] || settings.label || humanize(settings.key || name), read: readPath(segments) };
  });

  return { paperFields, sections, artifacts, compareRows };
}

/** Builds the scheme from a schema and installs it. Throws a SchemeError
 * with a readable message when the schema cannot drive the views. */
export function applyScheme(schema) {
  if (!schema || typeof schema !== 'object' || !schema.properties) throw new SchemeError('The schema has no properties.');
  const attributes = extractAttributes(schema);
  if (!attributes.some((a) => a.annotation?.role === 'year')) throw new SchemeError('No attribute has the role "year".');

  const dimensions = ordered(
    attributes.filter((a) => a.annotation?.uses?.includes(DIMENSION_USE)).map(toDimension),
    schema['x-ariadne']?.order,
  );
  const seen = new Map();
  dimensions.forEach((d) => {
    if (seen.has(d.key)) throw new SchemeError(`Two dimensions are called "${d.key}" (${seen.get(d.key)} and ${d.path}). Give one an x-ariadne "key".`);
    seen.set(d.key, d.path);
  });

  const roles = buildRoles(attributes, dimensions);
  const indicators = buildIndicators(schema, schema['x-ariadne']?.indicators);
  const detail = buildDetail(schema, attributes, roles, dimensions);
  const filterGroups = groupFacets(buildFacets(attributes, dimensions), schema['x-ariadne']?.filterGroups);

  DIMENSIONS.splice(0, DIMENSIONS.length, ...dimensions);
  installFilters(filterGroups);
  installRoles(roles);
  INDICATORS.splice(0, INDICATORS.length, ...indicators.items);
  INDICATOR_GROUP.label = indicators.label;
  installDetail(detail);
  return { attributes, dimensions, filterGroups, roles, indicators, detail };
}
