import React from 'react';
import ReactDOM from 'react-dom/client';
import { loadSchema, setDataSource } from '@/lib/data';
import { applyScheme } from '@/lib/scheme';
import { loadWorkspace } from '@/lib/workspace';
import { installReview } from '@/lib/review';
import { takeReviewerKey, forgetReviewerKey, loadReviewerRecords } from '@/lib/reviewerAccess';

const root = ReactDOM.createRoot(document.getElementById('root'));

/** Applies the visitor's own review when it is switched on, otherwise the
 * published schema. A review that cannot be applied falls back to the
 * published dataset, with a notice, so the site always starts. */
async function chooseSource() {
  // Read (and remove from the address bar) before anything else, so the key
  // never lingers in the URL, whichever dataset is shown.
  const reviewerKey = takeReviewerKey();
  const workspace = await loadWorkspace();
  if (workspace?.active) {
    try {
      applyScheme(workspace.schema);
      installReview(workspace.schema);
      setDataSource({ kind: 'workspace', name: workspace.name, schema: workspace.schema, papers: workspace.papers, savedAt: workspace.savedAt });
      return;
    } catch (e) {
      setDataSource({ kind: 'published', notice: `Your review "${workspace.name}" could not be shown: ${e.message} The published dataset is shown instead.` });
    }
  }
  applyScheme(await loadSchema());
  // A reviewer link (…/#k=<key>) replaces the anonymized papers with the full,
  // decrypted dataset; a missing file or wrong key falls back with a notice.
  if (reviewerKey) {
    try {
      setDataSource({ kind: 'published', reviewer: true, records: await loadReviewerRecords(reviewerKey) });
    } catch (e) {
      forgetReviewerKey();
      setDataSource({ kind: 'published', notice: `${e.message} The anonymized dataset is shown instead.` });
    }
  }
}

// The schema decides which attributes the views show, so it is applied
// before the app (and every module reading the dimensions) is loaded.
async function start() {
  try {
    await chooseSource();
  } catch (e) {
    root.render(
      <div className="main-layout">
        <div className="loading" role="alert">
          <p><strong>The site could not start.</strong></p>
          <p>{e.message}</p>
        </div>
      </div>
    );
    return;
  }
  const { default: App } = await import('@/App');
  root.render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}

start();
