/**
 * Reviewer access: the full dataset, encrypted, for reviewers who open the
 * site with a link of the form …/#k=<key>.
 *
 * public/data/review.enc holds the full dataset encrypted with AES-256-GCM
 * (12-byte IV followed by ciphertext and tag), written by
 * scripts/encrypt-review-data.mjs. The key travels only in the URL fragment,
 * which browsers never send to the server, so visitors stay anonymous and the
 * public file is useless without the link. Without a key, the site shows the
 * anonymized dataset as before.
 */

const BASE_PATH = import.meta.env.BASE_URL || '/';
export const REVIEW_FILE = 'review.enc';
const STORAGE_KEY = 'ariadne.reviewerKey';
const IV_BYTES = 12;

/** Reads the key from #k=<key>, keeps it for this browser tab so reloads and
 * navigation still work, and removes it from the address bar so it is not
 * copied along with links or shown in screenshots. Returns null without a
 * key. */
export function takeReviewerKey() {
  const match = window.location.hash.match(/(?:^#|&)k=([A-Za-z0-9_-]+)/);
  if (match) {
    try { sessionStorage.setItem(STORAGE_KEY, match[1]); } catch { /* private mode: key lives only in this page load */ }
    const rest = window.location.hash.slice(1).split('&').filter((part) => !part.startsWith('k=')).join('&');
    const url = window.location.pathname + window.location.search + (rest ? `#${rest}` : '');
    window.history.replaceState(window.history.state, '', url);
    return match[1];
  }
  try { return sessionStorage.getItem(STORAGE_KEY); } catch { return null; }
}

/** Forgets the key for this tab, e.g. after it failed to decrypt. */
export function forgetReviewerKey() {
  try { sessionStorage.removeItem(STORAGE_KEY); } catch { /* nothing stored */ }
}

function fromBase64Url(text) {
  const b64 = text.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (text.length % 4)) % 4);
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

/** Downloads and decrypts the full dataset. Throws when the file is missing
 * or the key does not fit it. */
export async function loadReviewerRecords(key) {
  const res = await fetch(`${BASE_PATH}data/${REVIEW_FILE}`);
  if (!res.ok) throw new Error('The full dataset is not available (any more).');
  const bytes = new Uint8Array(await res.arrayBuffer());
  let plain;
  try {
    const cryptoKey = await crypto.subtle.importKey('raw', fromBase64Url(key), 'AES-GCM', false, ['decrypt']);
    plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: bytes.slice(0, IV_BYTES) }, cryptoKey, bytes.slice(IV_BYTES));
  } catch {
    throw new Error('The reviewer link does not fit the full dataset.');
  }
  return JSON.parse(new TextDecoder().decode(plain));
}
