/**
 * Reads the attributes with a fixed job in the views: the Year role (time
 * axis of the Publication Timeline and Trends), the Keywords role (edges of
 * the Paper Metagraph, related papers, search) and the rows of the
 * Publication Timeline (overview.timelineRows, also the split of Trends).
 *
 * applyScheme (lib/scheme.js) sets the paths from the schema at startup.
 * Until then they read the BPM schema's paths.
 */
const readPath = (segments) => (node) => segments.reduce((cur, key) => (cur && typeof cur === 'object' ? cur[key] : undefined), node);

const state = {
  year: readPath(['metadata', 'year']),
  keywords: readPath(['contribution', 'keywords']),
  timelineRow: readPath(['metadata', 'track']),
  timelineRowKey: 'track',
  timelineRowOrder: [],
};

export function installRoles({ yearPath, keywordsPath, timelineRowPath, timelineRowKey, timelineRowOrder = [] }) {
  state.year = readPath(yearPath.split('.'));
  state.keywords = keywordsPath ? readPath(keywordsPath.split('.')) : () => [];
  state.timelineRow = timelineRowPath ? readPath(timelineRowPath.split('.')) : () => undefined;
  state.timelineRowKey = timelineRowKey || null;
  state.timelineRowOrder = timelineRowOrder;
}

/** The paper's year, or undefined. */
export const yearOf = (paper) => state.year(paper);

/** The paper's keywords; always a list. */
export const keywordsOf = (paper) => {
  const v = state.keywords(paper);
  return Array.isArray(v) ? v : v ? [v] : [];
};

/** The paper's row on the Publication Timeline (e.g. its track), or undefined. */
export const timelineRowOf = (paper) => {
  const v = state.timelineRow(paper);
  return Array.isArray(v) ? v[0] : v;
};

/** The key of the timeline-row attribute (e.g. "track"), or null. */
export const timelineRowKey = () => state.timelineRowKey;

/** Sorts timeline rows: those in the schema's order first, in that order
 * (x-ariadne "valueOrder" of the row attribute, else its value list), then
 * the others A to Z. */
export function compareTimelineRows(a, b) {
  const rank = (v) => {
    const i = state.timelineRowOrder.indexOf(v);
    return i === -1 ? Infinity : i;
  };
  return rank(a) - rank(b) || String(a).localeCompare(String(b));
}

/** The label of the single row when the schema has no timeline rows. */
export const SINGLE_ROW = 'All papers';

/** The paper's row on the Publication Timeline drawing: its timeline row,
 * or SINGLE_ROW for every paper when the schema has none. */
export const timelineBandOf = (paper) => (state.timelineRowKey ? timelineRowOf(paper) : SINGLE_ROW);
