import { conferenceFromVenue } from './venue';

const ACCENTS = { '"': '̈', "'": '́', '`': '̀', '^': '̂', '~': '̃', '=': '̄', '.': '̇', u: '̆', v: '̌', H: '̋', c: '̧', k: '̨', r: '̊' };
const SPECIAL = { ss: 'ß', aa: 'å', AA: 'Å', ae: 'æ', AE: 'Æ', oe: 'œ', OE: 'Œ', o: 'ø', O: 'Ø', l: 'ł', L: 'Ł', i: 'ı', j: 'ȷ' };
const SKIPPED_ENTRY_TYPES = new Set(['comment', 'preamble', 'string']);

const accent = (mark, ch) => (ch === 'ı' || ch === 'i' ? 'i' : ch) + ACCENTS[mark];

export function latexToText(value) {
  return String(value || '')
    .replace(/\\([`'^"~=.])\s*\{\s*\\?([A-Za-z])\s*\}/g, (_, m, ch) => accent(m, ch))
    .replace(/\\([`'^"~=.])\s*\\?([A-Za-z])/g, (_, m, ch) => accent(m, ch))
    .replace(/\\([uvHckr])\s*\{\s*\\?([A-Za-z])\s*\}/g, (_, m, ch) => accent(m, ch))
    .replace(/\\([uvHckr])\s+([A-Za-z])/g, (_, m, ch) => accent(m, ch))
    .replace(/\\(ss|aa|AA|ae|AE|oe|OE|o|O|l|L|i|j)(?![A-Za-z])\s*/g, (_, k) => SPECIAL[k])
    .replace(/\\([&%_$#])/g, '$1')
    .replace(/---/g, '—')
    .replace(/--/g, '–')
    .replace(/~/g, ' ')
    .replace(/\\[A-Za-z]+\*?\s*/g, '')
    .replace(/[{}]/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .normalize('NFC');
}

function readBalanced(text, start, open, close) {
  let depth = 0;
  for (let i = start; i < text.length; i += 1) {
    if (text[i] === '\\') { i += 1; continue; }
    if (text[i] === open) depth += 1;
    else if (text[i] === close) {
      depth -= 1;
      if (depth === 0) return i;
    }
  }
  return text.length;
}

function parseFields(body) {
  const fields = {};
  const keyEnd = body.indexOf(',');
  if (keyEnd < 0) return { key: body.trim(), fields };
  const key = body.slice(0, keyEnd).trim();
  let i = keyEnd + 1;
  const nameRe = /\s*,?\s*([A-Za-z][\w:.-]*)\s*=\s*/y;
  while (i < body.length) {
    nameRe.lastIndex = i;
    const m = nameRe.exec(body);
    if (!m) break;
    const name = m[1].toLowerCase();
    i = nameRe.lastIndex;
    let value = '';
    for (;;) {
      while (/\s/.test(body[i] || '')) i += 1;
      if (body[i] === '{') {
        const end = readBalanced(body, i, '{', '}');
        value += body.slice(i + 1, end);
        i = end + 1;
      } else if (body[i] === '"') {
        let j = i + 1;
        let depth = 0;
        while (j < body.length && !(body[j] === '"' && depth === 0 && body[j - 1] !== '\\')) {
          if (body[j] === '{') depth += 1;
          else if (body[j] === '}') depth -= 1;
          j += 1;
        }
        value += body.slice(i + 1, j);
        i = j + 1;
      } else {
        const m2 = /[^,#}\s]+/y;
        m2.lastIndex = i;
        const bare = m2.exec(body);
        if (bare) {
          value += bare[0];
          i = m2.lastIndex;
        }
      }
      while (/\s/.test(body[i] || '')) i += 1;
      if (body[i] === '#') { i += 1; continue; }
      break;
    }
    fields[name] = value;
  }
  return { key, fields };
}

export function parseBibtexEntries(text) {
  const entries = [];
  const src = String(text || '');
  const startRe = /@\s*([A-Za-z]+)\s*([{(])/g;
  let m;
  while ((m = startRe.exec(src))) {
    const open = m[2];
    const close = open === '{' ? '}' : ')';
    const openAt = m.index + m[0].length - 1;
    const end = readBalanced(src, openAt, open, close);
    const type = m[1].toLowerCase();
    startRe.lastIndex = end + 1;
    if (SKIPPED_ENTRY_TYPES.has(type)) continue;
    const { key, fields } = parseFields(src.slice(openAt + 1, end));
    entries.push({ type, key, fields });
  }
  return entries;
}

function splitTopLevel(value, separator) {
  const parts = [];
  let depth = 0;
  let last = 0;
  for (let i = 0; i < value.length; i += 1) {
    if (value[i] === '{') depth += 1;
    else if (value[i] === '}') depth -= 1;
    else if (depth === 0) {
      separator.lastIndex = i;
      const m = separator.exec(value);
      if (m) {
        parts.push(value.slice(last, i));
        last = i + m[0].length;
        i = last - 1;
      }
    }
  }
  parts.push(value.slice(last));
  return parts;
}

function bibtexAuthors(raw) {
  if (!raw) return [];
  return splitTopLevel(raw, /\s+and\s+/iy)
    .map((name) => {
      const parts = splitTopLevel(name, /\s*,\s*/y).map(latexToText).filter(Boolean);
      const full = parts.length >= 2 ? `${parts[parts.length - 1]} ${parts[0]}` : parts[0] || '';
      return full.replace(/\s+\d{4}$/, '').trim();
    })
    .filter((n) => n && !/^others$/i.test(n));
}

function cleanDoi(value) {
  return latexToText(value).replace(/^(?:https?:\/\/(?:dx\.)?doi\.org\/|doi:\s*)/i, '').trim();
}

export function bibtexEntryToDraft({ type, key, fields }) {
  const doi = cleanDoi(fields.doi);
  const year = (latexToText(fields.year) || latexToText(fields.date)).match(/\d{4}/)?.[0] || '';
  const keywordsRaw = latexToText(fields.keywords);
  const venue = fields.eventtitle || (type === 'article' ? '' : fields.booktitle) || '';
  const conference = conferenceFromVenue(latexToText(venue));
  return {
    label: key || latexToText(fields.title),
    title: latexToText(fields.title).replace(/\.$/, ''),
    authors: bibtexAuthors(fields.author),
    year,
    doi_or_url: doi ? `https://doi.org/${doi}` : latexToText(fields.url),
    keywords: keywordsRaw ? keywordsRaw.split(/[;,]/).map((k) => k.trim()).filter(Boolean) : [],
    conference_name: conference.name,
    conference_abbreviation: conference.abbreviation,
  };
}

export function parseBibtex(text) {
  const [first] = parseBibtexEntries(text);
  return first ? bibtexEntryToDraft(first) : { title: '', authors: [], year: '', doi_or_url: '', keywords: [] };
}

export function looksLikeBibtex(text) {
  return /@\s*[A-Za-z]+\s*[{(]/.test(text || '');
}

const NUMBER_MARKER = /^\s*(?:\[(\d+)\]|(\d+)\.)\s+/;

export function splitCitations(text) {
  const lines = String(text || '').replace(/\r/g, '').split('\n');
  const entries = [];
  let expected = null;
  let current = null;
  lines.forEach((line) => {
    const m = line.match(NUMBER_MARKER);
    const n = m ? Number(m[1] || m[2]) : null;
    if (m && (expected === null || n === expected)) {
      if (current) entries.push(current);
      current = [line.slice(m[0].length)];
      expected = n + 1;
    } else if (current) {
      current.push(line);
    } else {
      current = null;
    }
  });
  if (current) entries.push(current);
  if (entries.length >= 2) return entries.map(joinLines).filter(Boolean);

  const blocks = String(text || '').replace(/\r/g, '').split(/\n\s*\n/).map((b) => b.split('\n')).filter((b) => b.join('').trim());
  if (blocks.length === 1) {
    const only = blocks[0].map((l) => l.trim()).filter(Boolean);
    if (only.length > 1 && only.every((l) => /\b(?:19|20)\d{2}\b/.test(l))) return only.map((l) => joinLines([l.replace(NUMBER_MARKER, '')]));
  }
  return blocks.map((b) => joinLines([b[0].replace(NUMBER_MARKER, ''), ...b.slice(1)])).filter(Boolean);
}

function joinLines(lines) {
  return lines
    .map((l) => l.trim())
    .filter(Boolean)
    .reduce((acc, line) => {
      if (!acc) return line;
      if (/[a-zà-ÿ]-$/.test(acc) && /^[a-zà-ÿ]/.test(line)) return acc.slice(0, -1) + line;
      return `${acc} ${line}`;
    }, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const INITIALS = /^(?:[\p{Lu}][\p{Ll}]{0,2}\.[\s-]?)+$|^(?:[\p{L}]{1,3}\.){1,4}$/u;

function citationAuthors(part) {
  const tokens = part
    .replace(/\bet al\.?/gi, '')
    .replace(/\s*(?:&|\band\b)\s*/g, ', ')
    .split(/\s*,\s*/)
    .map((t) => t.trim())
    .filter(Boolean);
  const authors = [];
  for (let i = 0; i < tokens.length; i += 1) {
    const token = tokens[i];
    const next = tokens[i + 1];
    if (next && INITIALS.test(next) && !INITIALS.test(token)) {
      authors.push(`${next} ${token}`);
      i += 1;
    } else if (!INITIALS.test(token)) {
      authors.push(token);
    }
  }
  return authors.filter((a) => /\p{L}{2}/u.test(a));
}

const PUBLISHER_TAIL = /\.\s+(?=(?:pp?\.|vol\.|LNCS|LNBIP|CCIS|CEUR|Lecture Notes|[^.]*\((?:19|20)\d{2}\)\.?$))/;

function splitTitle(rest) {
  const inMatch = rest.match(/^(.*?[^\s])([.?!])\s+In:?\s+(.*)$/);
  if (inMatch && inMatch[1].length > 8) {
    return { title: inMatch[1] + (inMatch[2] === '.' ? '' : inMatch[2]), venue: inMatch[3], inProceedings: true };
  }
  const stop = rest.search(/(?<!\b(?:vol|no|pp|ed|eds|Vol|No|Ed|Eds|v|n))[.?!]\s+(?=[\p{Lu}0-9])/u);
  if (stop > 8) return { title: rest.slice(0, stop + (rest[stop] === '.' ? 0 : 1)), venue: rest.slice(stop + 2), inProceedings: false };
  return { title: rest.replace(/\s*\((?:19|20)\d{2}[a-z]?\)\.?\s*$/, ''), venue: '', inProceedings: false };
}

function venueConference(venue) {
  const cut = venue.replace(/^.*?\(eds?\.?\)\s*/i, '').split(PUBLISHER_TAIL)[0];
  return conferenceFromVenue(cut);
}

export function parseCitation(text) {
  const clean = joinLines(String(text || '').split('\n')).replace(NUMBER_MARKER, '');
  const doiMatch = clean.match(/10\.\d{4,9}\/[^\s,;]+/);
  const urlMatch = clean.match(/https?:\/\/\S+/);
  const years = [...clean.matchAll(/\(((?:19|20)\d{2})[a-z]?\)/g)].map((m) => m[1]);
  const year = years.length ? years[years.length - 1] : clean.match(/\b(?:19|20)\d{2}\b/)?.[0] || '';

  let title = '';
  let authors = [];
  let conference = { name: '', abbreviation: '' };

  const quoted = clean.match(/^(.*?)[“"]([^”"]{8,}?)[,.]?[”"]\s*,?\s*(.*)$/);
  const apa = clean.match(/^(.+?)\s*\(((?:19|20)\d{2})[a-z]?\)\.\s+(.+)$/);
  const lncsAt = clean.search(/\.:\s/);

  if (quoted) {
    title = quoted[2].trim();
    authors = citationAuthors(quoted[1].replace(/,\s*$/, ''));
    const after = quoted[3].match(/^in:?\s+(.*)$/i);
    if (after) conference = venueConference(after[1]);
  } else if (lncsAt > 0 && lncsAt < 500) {
    authors = citationAuthors(clean.slice(0, lncsAt + 1));
    const parts = splitTitle(clean.slice(lncsAt + 3));
    title = parts.title.replace(/,\s*vol\.\s*\d+$/i, '');
    if (parts.inProceedings) conference = venueConference(parts.venue);
  } else if (apa) {
    authors = citationAuthors(apa[1]);
    const parts = splitTitle(apa[3]);
    title = parts.title;
    if (parts.inProceedings) conference = venueConference(parts.venue);
  }

  const doi = doiMatch ? doiMatch[0].replace(/[.,;)]+$/, '') : '';
  return {
    label: title || clean.slice(0, 60),
    raw: clean,
    title: title.trim(),
    authors,
    year,
    doi_or_url: doi ? `https://doi.org/${doi}` : urlMatch ? urlMatch[0].replace(/[.,;)]+$/, '') : '',
    keywords: [],
    conference_name: conference.name,
    conference_abbreviation: conference.abbreviation,
  };
}
