import { doiKey } from './paperLookup';
import { extractAttributes } from './schemaMapping';
import { humanize } from './humanize';

/**
 * Papers for a visitor's own review: built from references (BibTeX, DOIs,
 * citations) or read from JSON, then checked against the review's schema.
 *
 * The check tells three things apart:
 *   errors      values that do not fit the schema (a code not in the list,
 *               text where a number belongs, "Other" without its name)
 *   uncoded     coded attributes with no value yet: normal while coding
 *   coded       coded attributes with a value
 * Coded attributes are the dimensions (x-ariadne use patterns.rowsColumns)
 * besides the Year role.
 */

const BIBLIOGRAPHIC = ['title', 'authors', 'doi_or_url', 'conference_name', 'conference_abbreviation'];

export const isEmpty = (v) => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);

export function nodeAt(schema, path) {
  let node = schema;
  for (const raw of path.split('.')) {
    node = node?.properties?.[raw.replace(/\[\]$/, '')];
    if (raw.endsWith('[]')) node = node?.items;
  }
  return node;
}

/** Sets a value at a dotted path (no list segments), creating objects. */
function setPath(record, path, value) {
  const keys = path.split('.');
  let cur = record;
  keys.slice(0, -1).forEach((k) => {
    if (!cur[k] || typeof cur[k] !== 'object') cur[k] = {};
    cur = cur[k];
  });
  cur[keys[keys.length - 1]] = value;
}

const read = (node, segments) => segments.reduce((cur, k) => (cur && typeof cur === 'object' ? cur[k] : undefined), node);

/** What the review's schema offers for references: the year and keywords
 * paths and the bibliographic fields it has. */
export function referenceTargets(schema) {
  const attributes = extractAttributes(schema);
  const role = (r) => attributes.find((a) => a.annotation?.role === r)?.path || null;
  return {
    yearPath: role('year'),
    keywordsPath: role('keywords'),
    metadata: BIBLIOGRAPHIC.filter((f) => nodeAt(schema, `metadata.${f}`)),
  };
}

/** An uncoded paper from a reference (see lib/paperLookup.js). */
export function paperFromReference(extracted, targets) {
  const record = { metadata: {}, contribution: {} };
  targets.metadata.forEach((f) => {
    const v = extracted[f];
    if (!isEmpty(v)) record.metadata[f] = f === 'authors' ? [...v] : String(v);
  });
  const year = Number(extracted.year);
  if (targets.yearPath && Number.isFinite(year) && year > 0) setPath(record, targets.yearPath, year);
  if (targets.keywordsPath && extracted.keywords?.length) setPath(record, targets.keywordsPath, [...extracted.keywords]);
  return record;
}

/** Papers from a JSON file: one paper or a list, each with metadata. Returns
 * null when the text is not JSON. */
export function papersFromJson(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  // A list of papers, one paper, or a downloaded review ({ papers: [...] }).
  const list = Array.isArray(data) ? data
    : Array.isArray(data?.papers) ? data.papers
    : data && typeof data === 'object' ? [data] : [];
  return list
    .filter((r) => r && typeof r === 'object' && !Array.isArray(r) && r.metadata && typeof r.metadata === 'object')
    .map((r) => {
      // Fields the site adds to papers it stores are not part of the review.
      const { _id, _userAdded, _userKey, _proposedAt, _editedAt, ...paper } = r;
      return { contribution: {}, ...paper };
    });
}

function kindProblem(attribute, value) {
  const allowed = attribute.values;
  const notAllowed = (v) => allowed && !allowed.includes(v);
  const list = (vs) => `${vs.map((v) => `"${v}"`).join(', ')} ${vs.length === 1 ? 'is' : 'are'} not in the list (${allowed.join(', ')})`;
  switch (attribute.kind) {
    case 'single': {
      const vs = Array.isArray(value) ? value : [value];
      if (vs.length > 1) return 'has several values; only one is allowed';
      if (typeof vs[0] !== 'string') return 'should be text';
      return notAllowed(vs[0]) ? list(vs) : null;
    }
    case 'multi': {
      if (!Array.isArray(value)) return 'should be a list';
      const bad = value.filter(notAllowed);
      return bad.length ? list(bad) : null;
    }
    case 'boolean': return typeof value === 'boolean' ? null : 'should be yes (true) or no (false)';
    case 'number': return typeof value === 'number' && Number.isFinite(value) ? null : 'should be a number';
    case 'text': return typeof value === 'string' ? null : 'should be text';
    case 'list': return Array.isArray(value) && value.every((v) => typeof v === 'string') ? null : 'should be a list of texts';
    default: return null;
  }
}

/** The paths holding the name of an "Other" value of the attribute, which
 * the schema may define as "<name>_other" next to it or "other" in the same
 * object. */
export function otherNamePaths(schema, attribute) {
  const segments = attribute.path.split('.');
  const parent = segments.slice(0, -1);
  return [
    [...parent, `${attribute.name}_other`].join('.'),
    ...(parent.length ? [[...parent, 'other'].join('.')] : []),
  ].filter((p) => p !== attribute.path && nodeAt(schema, p));
}

/** Where the name of an "Other" value is kept: the schema's field for it,
 * or else "<name>_other" next to the attribute, as Build Schema writes it.
 * A schema offering "other" without such a field still gets the name. */
export function otherNamePath(schema, attribute) {
  return otherNamePaths(schema, attribute)[0]
    || [...attribute.path.split('.').slice(0, -1), `${attribute.name}_other`].join('.');
}

const blank = (v) => isEmpty(typeof v === 'string' ? v.trim() : v);

/** Checks one paper against the schema: { errors: [text], uncoded: [label],
 * coded: [label] }. */
export function checkPaper(paper, schema, attributes = extractAttributes(schema)) {
  const errors = [];
  const uncoded = new Set();
  const coded = new Set();
  const artifacts = Array.isArray(paper.contribution?.artifacts) ? paper.contribution.artifacts : null;

  attributes.forEach((a) => {
    const label = humanize(a.annotation?.key || a.name);
    const segments = a.path.split('.');
    const inArtifact = segments[1] === 'artifacts[]';
    const nodes = inArtifact ? (artifacts || []).map((art, i) => ({ node: art, rel: segments.slice(2), where: artifacts.length > 1 ? ` (artifact ${i + 1})` : '' })) : [{ node: paper, rel: segments, where: '' }];
    const isDimension = a.annotation?.uses?.includes('patterns.rowsColumns') && a.annotation?.role !== 'year';
    let anyValue = false;
    nodes.forEach(({ node, rel, where }) => {
      const value = read(node, rel);
      if (isEmpty(value)) return;
      anyValue = true;
      const problem = kindProblem(a, value);
      if (problem) errors.push(`${label}${where}: ${problem}`);
      const chosen = Array.isArray(value) ? value : [value];
      if (chosen.some((v) => /^other$/i.test(v))) {
        const namePath = otherNamePath(schema, a).split('.');
        if (blank(read(node, inArtifact ? namePath.slice(2) : namePath))) errors.push(`${label}${where}: "Other" is chosen but its name is missing`);
      }
    });
    if (isDimension) (anyValue ? coded : uncoded).add(label);
  });
  return { errors, uncoded: [...uncoded], coded: [...coded] };
}

/** Checks a batch of papers and marks duplicates: by DOI or, without a DOI,
 * by title, against each other and against papers already in the review. */
export function checkPapers(papers, schema, existing = []) {
  const attributes = extractAttributes(schema);
  const keyOf = (p) => doiKey(p.metadata?.doi_or_url) || (p.metadata?.title ? `title:${p.metadata.title.trim().toLowerCase()}` : null);
  const seen = new Set(existing.map(keyOf).filter(Boolean));
  return papers.map((paper) => {
    const key = keyOf(paper);
    const duplicate = Boolean(key && seen.has(key));
    if (key) seen.add(key);
    return { paper, duplicate, ...checkPaper(paper, schema, attributes) };
  });
}
