const KNOWN_CONFERENCES = [
  ['BPM', 'International Conference on Business Process Management'],
  ['CAiSE', 'International Conference on Advanced Information Systems Engineering'],
  ['ICPM', 'International Conference on Process Mining'],
  ['ER', 'International Conference on Conceptual Modeling'],
  ['EDOC', 'International Enterprise Distributed Object Computing Conference'],
  ['ICSOC', 'International Conference on Service-Oriented Computing'],
  ['CoopIS', 'International Conference on Cooperative Information Systems'],
  ['RCIS', 'International Conference on Research Challenges in Information Science'],
  ['ECIS', 'European Conference on Information Systems'],
  ['ICIS', 'International Conference on Information Systems'],
  ['HICSS', 'Hawaii International Conference on System Sciences'],
  ['WSC', 'Winter Simulation Conference'],
  ['ICSE', 'International Conference on Software Engineering'],
];

const NOT_ACRONYMS = new Set(['IEEE', 'ACM', 'IFIP', 'LNCS', 'LNBIP', 'CCIS', 'CEUR', 'CEUR-WS', 'AIS', 'USA', 'UK', 'EU', 'PROC', 'II', 'III', 'IV']);
const SMALL_WORDS = new Set(['on', 'of', 'and', 'the', 'for', 'in', 'a', 'an', 'to', 'with']);
const KEYWORD = /\b(conference|symposium|workshop|congress|forum)\b/i;
const GENERIC_NAME = /^(?:(?:IEEE|ACM|IFIP)\s+)?(?:international|annual|european|joint|working)?\s*(?:international\s+)?(?:conference|symposium|workshop|congress)$/i;

const norm = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[^a-z0-9]/g, '');
const topicOf = (name) => norm(name).replace(/^(?:ieee|acm)?(?:international|european)?(?:conference|symposium)on/, '');

function titleCase(s) {
  if (s !== s.toLowerCase()) return s;
  return s.split(' ').map((w, i) => (i > 0 && SMALL_WORDS.has(w) ? w : w.charAt(0).toUpperCase() + w.slice(1))).join(' ');
}

function isAcronym(token) {
  if (!token || token.length < 2 || token.length > 12) return false;
  if (NOT_ACRONYMS.has(token.toUpperCase())) return false;
  return (token.match(/[A-Z]/g) || []).length >= 2 || /^[a-z]{2,8}$/.test(token);
}

function findAbbreviation(venue) {
  for (const m of venue.matchAll(/\(([A-Za-z][A-Za-z0-9&+-]{1,11})(?:\s*['’]?\s*\d{2,4})?\)/g)) {
    if (isAcronym(m[1])) return /[A-Z]/.test(m[1]) ? m[1] : m[1].toUpperCase();
  }
  for (const m of venue.matchAll(/(?:^|[\s,{])([A-Z][A-Za-z0-9&+-]*[A-Z][A-Za-z0-9&+-]*)\s*['’]?\s?((?:19|20)\d{2}|\d{2})\b/g)) {
    if (isAcronym(m[1])) return m[1];
  }
  return '';
}

function findName(venue) {
  const parts = venue.split(/\s+[-–—:]\s+|,\s*|\.\s+|;\s*/).map((p) => p.trim()).filter(Boolean);
  const idx = parts.findIndex((p) => KEYWORD.test(p));
  if (idx < 0) return '';
  let name = parts[idx]
    .replace(/^(?:(?:19|20)\d{2}|\d+(?:st|nd|rd|th))\s+/i, '')
    .replace(/^(?:(?:19|20)\d{2}|\d+(?:st|nd|rd|th))\s+/i, '')
    .replace(/\s*\([^)]*\)\s*$/, '')
    .replace(/\s+[A-Z][A-Za-z]*[A-Z][\w-]*\s*['’]?\s?(?:(?:19|20)\d{2}|\d{2})$/, '')
    .trim();
  if (GENERIC_NAME.test(name) && idx > 0 && !KEYWORD.test(parts[0])) name = `${name} on ${parts[0]}`;
  return titleCase(name);
}

export function conferenceFromVenue(raw) {
  if (!raw) return { name: '', abbreviation: '' };
  const venue = String(raw)
    .replace(/[{}]/g, '')
    .replace(/\s+/g, ' ')
    .replace(/^(?:in\s*:?\s*)?(?:proceedings|proc\.)\s+(?:of\s+)?(?:the\s+)?/i, '')
    .trim();
  return completeConference({ name: findName(venue), abbreviation: findAbbreviation(venue) }, venue);
}

export function completeConference({ name = '', abbreviation = '' }, venue = '') {
  const byAbbr = abbreviation && KNOWN_CONFERENCES.find(([a]) => a.toLowerCase() === abbreviation.toLowerCase());
  const byName = KNOWN_CONFERENCES.find(([, n]) => {
    if (name && (norm(n) === norm(name) || topicOf(n) === topicOf(name))) return true;
    return !name && venue && topicOf(n) === norm(venue);
  });
  const known = byAbbr || byName;
  if (!known) return { name, abbreviation };
  if (byAbbr && byName && byAbbr !== byName) return { name, abbreviation };
  if (byAbbr && name && topicOf(name) !== topicOf(known[1]) && norm(name) !== norm(known[1])) {
    return { name, abbreviation };
  }
  return { name: known[1], abbreviation: known[0] };
}
