import { DIMENSIONS } from './analysis';
import { FILTER_GROUPS, installFilters } from './facets';
import { checkPaper } from './reviewPapers';
import { extractAttributes } from './schemaMapping';
import { timelineRowKey } from './roles';

/**
 * What changes while the visitor's own review is shown instead of the
 * published dataset (see main.jsx and lib/workspace.js): the site texts and
 * lists written for the BPM dataset are left out, and every paper gets a
 * coding status, shown as a filter, in the stats and in the review banner.
 */

export const CODING = {
  coded: 'Fully coded',
  uncoded: 'Not fully coded',
  problems: 'With problems',
};

let review = null;
let statusCache = new WeakMap();

/** Sets the review's schema; called once at startup by main.jsx. */
export function installReview(schema) {
  review = { schema, attributes: extractAttributes(schema) };
  statusCache = new WeakMap();
  installCodingFilter();
}

/** The paper's coding status ('coded', 'uncoded' or 'problems'), or null
 * when no review is shown. */
export function codingStatusOf(paper) {
  if (!review) return null;
  let status = statusCache.get(paper);
  if (!status) {
    const { errors, uncoded } = checkPaper(paper, review.schema, review.attributes);
    status = errors.length ? 'problems' : uncoded.length ? 'uncoded' : 'coded';
    statusCache.set(paper, status);
  }
  return status;
}

/** Counts of papers per coding status. */
export function codingCounts(papers) {
  const counts = { coded: 0, uncoded: 0, problems: 0 };
  papers.forEach((p) => {
    const s = codingStatusOf(p);
    if (s) counts[s] += 1;
  });
  return counts;
}

/** Adds the Coding filter (Fully coded, Not fully coded, With problems)
 * after the schema's filters. */
function installCodingFilter() {
  const facet = { key: 'coding', label: 'Coding', raw: true, getValues: (paper) => [CODING[codingStatusOf(paper)]] };
  const groups = FILTER_GROUPS.filter((g) => g.id !== 'coding');
  // Without filter groups every filter is its own button; the Coding filter
  // then joins them.
  const ungrouped = groups.length === 1 && !groups[0].label;
  installFilters(ungrouped
    ? [{ ...groups[0], facets: [...groups[0].facets, facet] }]
    : [...groups, { id: 'coding', label: 'Coding', facets: [facet] }]);
}

/** The site config while a review is shown: the lists and texts describing
 * the BPM dataset are left out. The Type of Artifact and Type of Inquiry
 * lists (labels, colours, descriptions) stay only when the review codes the
 * same dimension. */
export function reviewConfig(config, { name }) {
  const has = (key) => DIMENSIONS.some((d) => d.key === key);
  const about = config.about || {};
  const license = about.license || {};
  const labels = config.visualization?.labels || {};
  const keepArtifactTypes = has('type_of_artifact') && config.typesOfArtifact;
  return {
    ...config,
    typesOfArtifact: keepArtifactTypes || undefined,
    typesOfInquiry: (has('type_of_inquiry') && config.typesOfInquiry) || undefined,
    visualization: {
      ...config.visualization,
      labels: {
        ...labels,
        stepsTitle: keepArtifactTypes ? labels.stepsTitle : undefined,
        landscapeDescription: `Papers by publication year${timelineRowKey() ? ` and ${timelineRowKey().replace(/_/g, ' ')}` : ''}. Hover for details, click to open.`,
        graphDescription: 'Explore connections between papers based on shared keywords and coded values.',
      },
    },
    about: {
      title: `About Your Review: ${name}`,
      introduction: `You are looking at your own review "${name}", stored in this browser only. The views show its papers, coded against its schema. Use the bar at the top to download it or to go back to the published dataset.`,
      schemaFile: about.schemaFile,
      pages: about.pages,
      ownReview: about.ownReview,
      license: { history: license.history, reference: license.reference, funding: license.funding },
    },
  };
}

function downloadJson(data, fileName) {
  const blob = new Blob([`${JSON.stringify(data, null, 2)}\n`], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

const fileBase = (name) => (name || 'my-review').trim().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'my-review';

const REVIEW_FILE = 'ariadne-lit-review';

/** Downloads the review as one JSON file: its name, schema and papers. Open
 * Review File (About) restores it; Load Papers reads its papers. */
export function downloadReview({ name, schema, papers }) {
  // Fields the site adds while showing papers are not part of the review.
  const clean = papers.map(({ _id, ...p }) => p);
  downloadJson({ format: REVIEW_FILE, version: 1, name, savedAt: new Date().toISOString(), schema, papers: clean }, `${fileBase(name)}.review.json`);
}

/** The review in a file made by downloadReview, or null when the text is
 * not one. */
export function parseReviewFile(text) {
  let data;
  try {
    data = JSON.parse(text);
  } catch {
    return null;
  }
  if (!data || data.format !== REVIEW_FILE || !data.schema || typeof data.schema !== 'object' || !Array.isArray(data.papers)) return null;
  return { name: typeof data.name === 'string' ? data.name : 'My review', schema: data.schema, papers: data.papers };
}

/** Restarts the site on Overview, e.g. after switching the review on or
 * off. Filters in the address may not exist in the other schema. */
export function restartSite() {
  window.location.assign(import.meta.env.BASE_URL || '/');
}
