import { completeConference, conferenceFromVenue } from './venue';

const CROSSREF_BASE = 'https://api.crossref.org/works';
const PROCEEDINGS_TYPES = new Set(['proceedings-article', 'book-chapter', 'proceedings']);
const SERIES_TITLE = /^(?:lecture notes|communications in computer|ceur|ifip advances|advances in intelligent)/i;

const wait = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function crossrefFetch(url, attempts = 4) {
  for (let i = 0; ; i += 1) {
    let res = null;
    try {
      res = await fetch(url);
    } catch {
      if (i >= attempts - 1) throw new Error('Could not reach CrossRef (the lookup service may be busy). Check the fields by hand.');
    }
    if (res && ((res.status !== 429 && res.status < 500) || i >= attempts - 1)) return res;
    const retryAfter = Number(res?.headers.get('retry-after'));
    await wait(retryAfter > 0 ? retryAfter * 1000 : 1500 * 2 ** i);
  }
}

/** Pulls a bare DOI out of a pasted DOI, doi.org URL, or DOI embedded in a
 * longer string of text. */
function extractDoi(input) {
  const match = input.trim().match(/10\.\d{4,9}\/\S+/);
  const doi = match ? match[0] : input.trim();
  return doi.replace(/[.,;]+$/, '');
}

export function extractDois(text) {
  return [...new Set([...String(text || '').matchAll(/10\.\d{4,9}\/[^\s,;"'<>]+/g)].map((m) => m[0].replace(/[.,;)]+$/, '')))];
}

function conferenceOf(message) {
  const assertion = (name) => (message.assertion || []).find((a) => a.name === name)?.value?.trim() || '';
  const name = assertion('conference_name');
  const abbreviation = assertion('conference_acronym');
  if (name || abbreviation) return completeConference({ name, abbreviation });
  if (message.event?.name) {
    const fromEvent = conferenceFromVenue(message.event.name);
    return { name: fromEvent.name, abbreviation: message.event.acronym || fromEvent.abbreviation };
  }
  if (!PROCEEDINGS_TYPES.has(message.type)) return { name: '', abbreviation: '' };
  for (const title of message['container-title'] || []) {
    if (SERIES_TITLE.test(title)) continue;
    const found = conferenceFromVenue(title);
    if (found.name || found.abbreviation) return found;
  }
  return { name: '', abbreviation: '' };
}

function normalizeMessage(message, fallbackDoi = '') {
  const authors = (message.author || [])
    .map((a) => [a.given, a.family].filter(Boolean).join(' ').trim() || a.name || '')
    .filter(Boolean);
  const dateParts =
    message.published?.['date-parts']?.[0] ||
    message['published-print']?.['date-parts']?.[0] ||
    message['published-online']?.['date-parts']?.[0] ||
    message.issued?.['date-parts']?.[0] ||
    [];
  const conference = conferenceOf(message);
  const doi = message.DOI || fallbackDoi;
  const clean = (s) => (s || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  const mainTitle = clean(message.title?.[0]);
  const subtitle = clean(message.subtitle?.[0]);
  return {
    title: subtitle && !mainTitle.toLowerCase().includes(subtitle.toLowerCase()) ? `${mainTitle}: ${subtitle}` : mainTitle,
    authors,
    year: dateParts[0] || '',
    doi_or_url: doi ? `https://doi.org/${doi}` : '',
    conference_name: conference.name,
    conference_abbreviation: conference.abbreviation,
  };
}

/** Looks up a DOI against the CrossRef public API (no key required) and
 * normalizes the response to this app's metadata shape. Throws with a
 * message suitable for display if the DOI isn't found or the network call
 * fails — the caller falls back to manual entry either way. */
export async function fetchByDoi(input) {
  const doi = extractDoi(input);
  if (!doi) throw new Error('Enter a DOI first.');

  const res = await crossrefFetch(`${CROSSREF_BASE}/${encodeURIComponent(doi)}`);
  if (!res.ok) {
    throw new Error(res.status === 404 ? `No paper found for DOI "${doi}".` : `DOI lookup failed (${res.status}).`);
  }

  const { message } = await res.json();
  return normalizeMessage(message, doi);
}

const words = (s) => (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]+/g) || [];

function titleSimilarity(a, b) {
  const wa = words(a);
  const wb = words(b);
  if (!wa.length || !wb.length) return 0;
  const counts = new Map();
  wa.forEach((w) => counts.set(w, (counts.get(w) || 0) + 1));
  let shared = 0;
  wb.forEach((w) => {
    if (counts.get(w) > 0) {
      shared += 1;
      counts.set(w, counts.get(w) - 1);
    }
  });
  return (2 * shared) / (wa.length + wb.length);
}

export async function searchByReference({ title, year, query }) {
  if (!title) return null;
  const params = new URLSearchParams({ 'query.bibliographic': (query || title).slice(0, 400), rows: '3' });
  const res = await crossrefFetch(`${CROSSREF_BASE}?${params}`);
  if (!res.ok) return null;
  const { message } = await res.json();
  for (const item of message.items || []) {
    const found = normalizeMessage(item);
    const sameYear = !year || !found.year || Math.abs(Number(year) - Number(found.year)) <= 1;
    if (sameYear && titleSimilarity(title, found.title) >= 0.9) return found;
  }
  return null;
}
