/**
 * The filters, in groups: [{ id, label, facets: [{ key, label, sortByValue,
 * raw, getValues(paper) }] }]. A group without a label shows each of its
 * filters as its own button. Filled from the schema at startup by
 * applyScheme (lib/scheme.js), in place, so modules importing them see the
 * schema's filters.
 */
export const FILTER_GROUPS = [];
export const FILTER_FACETS = [];

export function installFilters(groups) {
  FILTER_GROUPS.splice(0, FILTER_GROUPS.length, ...groups);
  FILTER_FACETS.splice(0, FILTER_FACETS.length, ...groups.flatMap((g) => g.facets));
  cache = new WeakMap();
}

let cache = new WeakMap();
export function facetValues(paper) {
  let v = cache.get(paper);
  if (!v) {
    v = Object.fromEntries(FILTER_FACETS.map((f) => [f.key, f.getValues(paper)]));
    cache.set(paper, v);
  }
  return v;
}

export function matchesFilters(paper, filters, exceptKey = null) {
  const values = facetValues(paper);
  return FILTER_FACETS.every((f) => {
    if (f.key === exceptKey) return true;
    const sel = filters[f.key];
    return !sel || sel.length === 0 || sel.some((v) => values[f.key].includes(v));
  });
}

export const activeFilterCount = (filters) =>
  Object.values(filters).reduce((s, v) => s + (v?.length || 0), 0);

export function facetOptions(papers, facet, filters) {
  const totals = new Map();
  const counts = new Map();
  papers.forEach((p) => {
    const vals = facetValues(p)[facet.key];
    const passes = matchesFilters(p, filters, facet.key);
    vals.forEach((v) => {
      totals.set(v, (totals.get(v) || 0) + 1);
      if (passes) counts.set(v, (counts.get(v) || 0) + 1);
    });
  });
  return [...totals.keys()]
    .map((value) => ({ value, count: counts.get(value) || 0, total: totals.get(value) }))
    .sort((a, b) => (facet.sortByValue ? a.value.localeCompare(b.value) : b.total - a.total || a.value.localeCompare(b.value)));
}
