/**
 * What the paper detail panel, the artifact cards and the Compare table show,
 * built from the schema at startup by applyScheme (lib/scheme.js):
 *
 *   DETAIL.paperFields     fields directly under metadata or contribution
 *                          (besides the bibliographic header and the roles)
 *   DETAIL.sections        one per object under contribution, e.g. Research
 *                          Components: { title, fields }
 *   DETAIL.artifacts       the per-artifact fields, shown as one card per
 *                          artifact: { title, fields }
 *   DETAIL.compareRows     the coded rows of the Compare table
 *
 * A field is { path, label, read(node), showWith?(node) }: read takes the
 * paper (or, for artifact fields, the artifact).
 */
export const DETAIL = {
  paperFields: [],
  sections: [],
  artifacts: { title: 'Artifacts', fields: [] },
  compareRows: [],
};

export function installDetail(plan) {
  Object.assign(DETAIL, plan);
}

const isEmpty = (v) => v === undefined || v === null || v === '' || (Array.isArray(v) && v.length === 0);

/** Whether the field shows anything for this paper or artifact. */
export const fieldShows = (field, node) => !isEmpty(field.read(node)) && (!field.showWith || !isEmpty(field.showWith(node)));

/** Whether a section has at least one field to show. */
export const sectionShows = (section, node) => section.fields.some((f) => fieldShows(f, node));
