import { extractDois, fetchByDoi, searchByReference } from './crossref';
import { bibtexEntryToDraft, looksLikeBibtex, parseBibtexEntries, parseCitation, splitCitations } from './referenceExtract';

/**
 * Reads papers from BibTeX, DOIs or plain-text citations and completes them
 * from Crossref. Shared by Add Paper and the import into a visitor's own
 * review. A reference is { source: 'bibtex' | 'doi' | 'citation',
 * extracted: { title, authors, year, doi_or_url, keywords?,
 * conference_name, conference_abbreviation, label?, raw? } }.
 */

/** A DOI or doi.org URL in a form that compares equal. */
export const doiKey = (s) => (s || '').trim().toLowerCase().replace(/^https?:\/\/(dx\.)?doi\.org\//, '');

function mergeLookup(base, found, preferFound) {
  const pick = (a, b) => (preferFound ? b || a : a || b);
  const hasConference = (x) => Boolean(x.conference_name || x.conference_abbreviation);
  const conference = (preferFound && hasConference(found)) || !hasConference(base) ? found : base;
  return {
    ...base,
    title: pick(base.title, found.title),
    authors: pick(base.authors?.length ? base.authors : null, found.authors?.length ? found.authors : null) || [],
    year: pick(base.year, found.year),
    doi_or_url: base.doi_or_url || found.doi_or_url,
    conference_name: conference.conference_name || '',
    conference_abbreviation: conference.conference_abbreviation || '',
  };
}

export function parseReferences(text, mode) {
  if (mode === 'bibtex' || looksLikeBibtex(text)) {
    return parseBibtexEntries(text).map((entry) => ({ source: 'bibtex', extracted: bibtexEntryToDraft(entry) }));
  }
  if (mode === 'doi') {
    return extractDois(text).map((doi) => ({ source: 'doi', extracted: { label: doi, doi_or_url: `https://doi.org/${doi}` } }));
  }
  return splitCitations(text).map((c) => ({ source: 'citation', extracted: parseCitation(c) }));
}

export async function lookUpReference({ source, extracted }) {
  const doi = extractDois(extracted.doi_or_url)[0];
  try {
    if (doi) {
      const found = await fetchByDoi(doi);
      return { extracted: source === 'doi' ? found : mergeLookup(extracted, found, source === 'citation') };
    }
    const found = await searchByReference({ title: extracted.title, year: extracted.year, query: extracted.raw });
    if (found) return { extracted: mergeLookup(extracted, found, source === 'citation') };
    return { extracted, notice: 'No matching DOI was found in CrossRef. Enter the DOI or a URL by hand.' };
  } catch (e) {
    return { extracted, notice: e.message || 'The CrossRef lookup failed. Check the fields by hand.' };
  }
}

